import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


def _parse_bound(payload, param, errors):
    """Parse one bound while retaining all local parsing failures."""
    if param not in payload:
        errors.append(build_rejection(param, "missing required date", {"value": None}))
        return None

    value = payload[param]
    if not isinstance(value, str):
        errors.append(
            build_rejection(
                param,
                "must be an ISO 8601 date string",
                {"value": value},
            )
        )
        return None

    try:
        return parse_bound(value)
    except (TypeError, ValueError):
        errors.append(
            build_rejection(
                param,
                "must be a valid ISO 8601 date string",
                {"value": value},
            )
        )
        return None


def _utc_payload(start, end):
    """Return the canonical values used for the range comparison."""
    return {
        "start_utc": start.astimezone(DEFAULT_TIMEZONE).isoformat(),
        "end_utc": end.astimezone(DEFAULT_TIMEZONE).isoformat(),
        "naive_timezone_policy": MISSING_TZ_POLICY,
        "default_timezone": "UTC",
    }


def _is_reversed_fallback_range(start, end):
    """Identify the service's ambiguous fall-back local-time case."""
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    return (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    )


def validate_range(payload):
    if not isinstance(payload, dict):
        return [
            build_rejection(
                "query",
                "must be an object",
                {"value": payload},
            )
        ]

    errors = []
    start = _parse_bound(payload, "start_date", errors)
    end = _parse_bound(payload, "end_date", errors) if "end_date" in payload else None

    # An omitted end is a valid open-ended query. Parsing failures are still
    # returned above, and no outbound call is made for those failures.
    if start is None or ("end_date" in payload and end is None):
        return errors
    if "end_date" not in payload:
        return errors

    utc_values = _utc_payload(start, end)
    if end.astimezone(DEFAULT_TIMEZONE) < start.astimezone(DEFAULT_TIMEZONE):
        errors.append(
            build_rejection(
                "date_range",
                "end_date must be greater than or equal to start_date after UTC normalization",
                utc_values,
            )
        )

    if _is_reversed_fallback_range(start, end):
        errors.append(
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range has an earlier local end clock",
                {
                    **utc_values,
                    "start_local": start.replace(tzinfo=None).isoformat(),
                    "end_local": end.replace(tzinfo=None).isoformat(),
                    "start_offset": str(start.utcoffset()),
                    "end_offset": str(end.utcoffset()),
                },
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

